/**
 * Traductions de l'interface ELEGANZ Secourable (prompt du 13 oct. 2026, §21 et
 * réponse du propriétaire du 13 oct. 2026) — PORTÉE VOLONTAIREMENT LIMITÉE :
 * seuls les menus, titres, boutons et libellés de champs sont traduits,
 * jamais les données saisies par l'utilisateur (noms d'activités,
 * observations...), qui restent dans la langue où elles ont été tapées.
 *
 * Deux groupes de langues, décision explicite du propriétaire :
 * - Langues « pilotes » (français, anglais, espagnol, arabe, portugais,
 *   swahili) : utilisables pour piloter toute la plateforme, confiance de
 *   traduction élevée.
 * - Les 4 langues nationales de la RDC (lingala, kikongo, tshiluba, en plus
 *   du swahili déjà listé ci-dessus) : ajoutées uniquement pour aider à la
 *   compréhension des menus et options, pas comme langues de pilotage
 *   complètes. Lingala, kikongo et tshiluba sont des langues à faibles
 *   ressources pour une traduction automatique : LocaleContext.tsx affiche
 *   un bandeau invitant à une relecture par un locuteur natif tant que ce
 *   n'est pas fait (voir REVUE_RECOMMANDEE plus bas).
 */

export type Locale = "fr" | "en" | "es" | "ar" | "pt" | "sw" | "ln" | "kg" | "lu";

export const LOCALES: { code: Locale; label: string; rtl?: boolean; reviewRecommended?: boolean }[] = [
  { code: "fr", label: "Français" },
  { code: "en", label: "English" },
  { code: "es", label: "Español" },
  { code: "ar", label: "العربية", rtl: true },
  { code: "pt", label: "Português" },
  { code: "sw", label: "Kiswahili" },
  { code: "ln", label: "Lingála", reviewRecommended: true },
  { code: "kg", label: "Kikongo", reviewRecommended: true },
  { code: "lu", label: "Tshiluba", reviewRecommended: true },
];

/** Langues dont la traduction mérite une relecture par un locuteur natif avant usage étendu. */
export const REVUE_RECOMMANDEE: Locale[] = ["ln", "kg", "lu"];

export const DEFAULT_LOCALE: Locale = "fr";

