  accueil_h1: "El comercio congoleño, del mostrador a la vitrina",
  accueil_heroTexte: "ELEGANZ es un ecosistema pensado para los comerciantes e independientes de Kinshasa: llevar las cuentas, gestionar una tienda y vender en línea — tres herramientas separadas, una sola plataforma, construida y operada desde la RDC.",
  accueil_choisirOutil: "Elegir mi herramienta",
  accueil_aProposLien: "Acerca de ELEGANZ",
  accueil_h2Outils: "¿Qué herramienta le conviene?",
  accueil_outilsIntro: "No necesita conocer la plataforma de antemano: responda la pregunta que le concierne.",
  accueil_questionComptable: "¿Tiene una actividad, sin tienda ni catálogo?",
  accueil_descComptable: "— ventas y gastos por divisa, deudas y cuentas por cobrar, alquileres, pagos a trabajadores, agenda de vencimientos y resúmenes exportables. Seis meses gratis, luego 1 $ al mes.",
