  apropos_intro: "إليغانز نظام متكامل صمم للتجارة الكونغولية، من البائع غير الرسمي الصغير إلى المتجر الراسخ: متابعة الحسابات، تسيير متجر والبيع عبر الإنترنت — ثلاث أدوات منفصلة، منصة واحدة، مبنية ومُدارة من كينشاسا. أما التوصيل، فيبقى حاليًا منظمًا من قبل كل متجر بسائقيه الخاصين، تحت مسؤوليته الخاصة.",
  apropos_descComptable: "دفتر تسيير يومي لأي نشاط — تجارة، إيجار، خدمة، مركبة — بدون متجر أو كتالوج يُنشأ. مبيعات ومصاريف بالعملة، ديون ومستحقات بتسديد جزئي، تسيير الإيجارات، مدفوعات العمال، جدول للمواعيد، رسوم بيانية وملخصات قابلة للتصدير، وملف تمهيدي لطلب تمويل. ستة أشهر مجانًا، ثم دولار واحد شهريًا.",
  apropos_descGestion: "صندوق ومخزون وفواتير متجر، مع سعر يتم التفاوض عليه عند الدفع، استيراد/تصدير الكتالوج بصيغة إكسل، بيانات نشاط موثقة، تتبع الطلبات والنزاعات، تسيير الفريق، ووضعية بدون اتصال تحمي كل عملية بيع حتى عند انقطاع الشبكة.",
  apropos_descMarket: "الواجهة التي تجمع البائعين والمشترين الكونغوليين في سوق واحد عبر الإنترنت، في كل القطاعات. بحث، صفحة المنتج، سلة، طلب، تتبع التوصيل وآراء العملاء، للشراء الكونغولي دون مغادرة المنزل.",
  apropos_h2Engagement: "ما لا نقوم به",
  apropos_texteEngagement: "لا يُعرض أي مستند صادر عن إليغانز كفاتورة ضريبية معتمدة ما لم تُؤكَّد المصادقة الرسمية: يختار كل متجر، حسب كل حالة، بين مستند تجاري عادي وفاتورة ضريبية، ولا يُستخدم أحدهما بدل الآخر أبدًا. ولا يُعرض أي دفع عبر الإنترنت اليوم كمؤكد — تتم تسوية الطلبات عند التسليم، نقدًا أو عبر الدفع عبر الهاتف المحمول، بكل شفافية.",
  footer_tagline_accueil: "بيت واحد، عدة غرف: المتجر والواجهة والطريق.",
  footer_tagline_gestion: "الصندوق والمتجر، منظمان تمامًا.",
