  apropos_h1: "Uma casa, três divisões",
  apropos_intro: "A ELEGANZ é um ecossistema pensado para o comércio congolês, do pequeno vendedor informal à loja estabelecida: manter as contas, gerir uma loja e vender online — três ferramentas separadas, uma só plataforma, construída e operada a partir de Kinshasa. A entrega, por agora, continua organizada por cada loja com os seus próprios entregadores, sob a sua própria responsabilidade.",
  apropos_descComptable: "Um caderno de gestão diária para qualquer atividade — comércio, aluguer, serviço, veículo — sem loja nem catálogo a criar. Vendas e despesas por moeda, dívidas e créditos com pagamento parcial, gestão de alugueres, pagamentos a trabalhadores, agenda de vencimentos, gráficos e resumos exportáveis, e um dossiê preparatório para um pedido de financiamento. Seis meses grátis, depois 1 $ por mês.",
  apropos_descGestion: "A caixa, o stock e as faturas de uma loja, com preço negociado no pagamento, importação/exportação Excel do catálogo, extratos de atividade certificados, acompanhamento de pedidos e litígios, gestão de equipa, e um modo offline que protege cada venda mesmo em caso de corte de rede.",
  apropos_descMarket: "A vitrine que reúne vendedores e compradores congoleses num só mercado online, em todos os setores. Pesquisa, ficha de produto, carrinho, pedido, acompanhamento de entrega e avaliações de clientes, para comprar congolês sem saír de casa.",
  apropos_h2Engagement: "O que não fazemos",
  apropos_texteEngagement: "Nenhum documento emitido na ELEGANZ é apresentado como fatura fiscal homologada enquanto a homologação oficial não for confirmada: cada loja escolhe, caso a caso, entre um documento comercial comum e uma fatura fiscal, nunca um pelo outro. E nenhum pagamento online é hoje apresentado como confirmado — o pagamento dos pedidos é feito na entrega, em dinheiro ou mobile money, com total transparência.",
  footer_tagline_accueil: "Uma casa, várias divisões: a loja, a vitrine e a estrada.",
  footer_tagline_gestion: "A caixa e a loja, em ordem.",
  footer_tagline_admin: "A plataforma, supervisionada num piscar de olhos.",
