  accueil_h1: "Biashara ya Kikongo, kutoka dukani hadi kwenye duka la mtandaoni",
  accueil_heroTexte: "ELEGANZ ni mfumo ulioundwa kwa wafanyabiashara na watu binafsi wa Kinshasa: kutunza hesabu, kusimamia duka na kuuza mtandaoni — vifaa vitatu tofauti, jukwaa moja, lililojengwa na kuendeshwa kutoka DRC.",
  accueil_choisirOutil: "Chagua chombo changu",
  accueil_aProposLien: "Kuhusu ELEGANZ",
  accueil_h2Outils: "Chombo kipi kinakufaa?",
  accueil_outilsIntro: "Hakuna haja ya kujua jukwaa mapema: jibu swali linalokuhusu.",
  accueil_questionComptable: "Una shughuli, bila duka au katalogi?",
  accueil_descComptable: "— mauzo na matumizi kwa sarafu, madeni na mapokeo, kodi za nyumba, malipo ya wafanyakazi, kalenda ya makataa na muhtasari unaoweza kuhamishwa. Miezi sita bure, kisha $1 kwa mwezi.",
  accueil_ouvrirCarnet: "Fungua kitabu changu",
  accueil_questionGestion: "Una duka, na sanduku na hisa za kusimamia?",
  accueil_descGestion: "— sanduku, hisa, risiti na maagizo ya duka lako, pamoja na usafirishaji unaofuatiliwa na timu iliyojengwa ndani, kutoka dukani hadi dashibodi ya jioni.",
  accueil_ouvrirCaisse: "Fungua sanduku langu",
  accueil_questionMarket: "Unatafuta kununua au kuuza mtandaoni?",
  accueil_descMarket: "— duka la mtandaoni linalounganisha wauzaji na wanunuzi wa Kikongo, katika sekta zote: utafutaji, agizo na usafirishaji unaofuatiliwa, popote ulipo.",
  accueil_parcourirVitrine: "Angalia duka la mtandaoni",
  apropos_h1: "Nyumba moja, vyumba vitatu",
  apropos_intro: "ELEGANZ ni mfumo ulioundwa kwa biashara ya Kikongo, kutoka muuzaji mdogo asiye rasmi hadi duka lililowekwa: kutunza hesabu, kusimamia duka na kuuza mtandaoni — vifaa vitatu tofauti, jukwaa moja, lililojengwa na kuendeshwa kutoka Kinshasa. Usafirishaji, kwa sasa, unapangwa na kila duka kwa madereva wake, chini ya jukumu lake.",
  apropos_descComptable: "Kitabu cha usimamizi wa kila siku kwa shughuli yoyote — biashara, ukodishaji, huduma, gari — bila duka au katalogi ya kuunda. Mauzo na matumizi kwa sarafu, madeni na mapokeo kwa malipo ya sehemu, usimamizi wa ukodishaji, malipo ya wafanyakazi, kalenda ya makataa, michoro na muhtasari unaoweza kuhamishwa, na faili la maandalizi kwa ombi la ufadhili. Miezi sita bure, kisha $1 kwa mwezi.",
  apropos_descGestion: "Sanduku, hisa na risiti za duka, na bei inayojadiliwa wakati wa malipo, uhamisho wa Excel wa katalogi, taarifa za shughuli zilizothibitishwa, ufuatiliaji wa maagizo na migogoro, usimamizi wa timu, na hali ya nje ya mtandao inayolinda mauzo yote hata wakati wa kukatika kwa mtandao.",
  apropos_descMarket: "Duka la mtandaoni linalounganisha wauzaji na wanunuzi wa Kikongo katika soko moja la mtandaoni, katika sekta zote. Utafutaji, ukurasa wa bidhaa, kikapu, agizo, ufuatiliaji wa usafirishaji na maoni ya wateja, kununua bidhaa za Kikongo bila kuacha nyumbani.",
  apropos_h2Engagement: "Tusichofanya",
  apropos_texteEngagement: "Hakuna hati iliyotolewa kwenye ELEGANZ inayowasilishwa kama ankara ya kodi iliyoidhinishwa hadi uidhinishaji rasmi uthibitishwe: kila duka huchagua, kwa kila hali, kati ya hati ya kibiashara ya kawaida na ankara ya kodi, kamwe moja badala ya nyingine. Na hakuna malipo ya mtandaoni leo yanayowasilishwa kama yaliyothibitishwa — malipo ya maagizo hufanywa wakati wa uwasilishaji, kwa fedha taslimu au mobile money, kwa uwazi kamili.",
  footer_tagline_accueil: "Nyumba moja, vyumba vingi: duka, dirisha la maonyesho na barabara.",
