  accueil_descComptable: "— mteka ye mbongo ya kubimisa na zimbongo, maniongo ye bina bekubikudila, mbongo ya nzo, nsendo ya basadi, kalandari ya bilumbu ya kufuta ye mabakulu ma kubongisa. Ngonda nsambwadi ya mfwenina, na nima dola 1 na ngonda.",
  accueil_ouvrirCarnet: "Zibula kahya kiame",
  accueil_questionGestion: "Nge ke na zandu, na kesi ye bima ya kutwadisa?",
  accueil_descGestion: "— kesi, bima, fatula ye commande ya zandu kiaku, ye ntwadisulu yina belandaka ye kibuka ya kisalu, tuka ku zandu kuna tableau ya nkokila.",
  accueil_ouvrirCaisse: "Zibula kesi kiame",
  accueil_questionMarket: "Nge ke zola kusumba to kuteka va site?",
  accueil_descMarket: "— kisika yina kekutanisa bantekisi ye basumbi ya Kongo, mu mintu mioso : lusaka, commande ye ntwadisulu yina belandaka, konso kisika nge wena.",
  accueil_parcourirVitrine: "Tala kisika kia nteko",
  apropos_h1: "Nzo mosi, bisika tatu",
  apropos_intro: "ELEGANZ ke kima ya ntwadisa yina bayikidi sambu na mvwandu ya Kongo, tuka na ntekisi ya fioti kuna zandu ya nene : kutanina zimbongo, kutwadisa zandu ye ku teka va site — bisadilu tatu ya mpila mpila, kima mosi, yina basala ye bansala tuka na Kinshasa. Ntwadisulu, yawu, kele kaka kubongisama na zandu konso mosi na bansofele na yau, na nsi ya mukumba na yau mosi.",
  apropos_descComptable: "Kahya ya kutwadisa lumbu na lumbu sambu na kisalu yoso — mvwandu, kufutisa nzo, kisalu, motuka — kaka ve na zandu to catalogue ya kusala. Mteka ye mbongo ya kubimisa na zimbongo, maniongo ye bina bekubikudila na kufuta fioti, kutwadisa kufutisa nzo, nsendo ya basadi, kalandari ya bilumbu ya kufuta, bifwani ye mabakulu ma kubongisa, ye dossier ya ntete sambu na lomba mbongo. Ngonda nsambwadi ya mfwenina, na nima dola 1 na ngonda.",
  apropos_descGestion: "Kesi, bima ye fatula ya zandu, na ntalu yina beyikisana na ntangu ya kufuta, kukotisa/kubimisa catalogue na Excel, malapolo ma kisalu makwikizwa, kulanda ma commande ye makani, kutwadisa kibuka, ye mpila ya kondwa site yina kekeba mteka yoso ata na ntangu réseau ekatukidi.",
  apropos_descMarket: "Kisika yina kekutanisa bantekisi ye basumbi ya Kongo na zandu mosi ya site, mu mintu mioso. Lusaka, lukanda lua kima, kibuka, commande, kulanda ntwadisulu ye mabanza ma baklienti, sambu na sumba bima ya Kongo kondwa kubika na nzo.",
  apropos_h2Engagement: "Mambu tusalaka ve",
  apropos_texteEngagement: "Kisalu ko ke bimisama na ELEGANZ kemonikaka diaka fatula ya mpaku yakwikizwa kana homologation ya leta kemonikaka ve : zandu konso mosi kesolaka, kolanda mbandu, va kati ya kisalu ya mvwandu ya mbote ye fatula ya mpaku, kasi ve mosi sambu na mosi wankaka. Ye lufutu ko ya site kemonikaka lelo diaka lukwikizu — lufutu ya ma commande kesalamaka na ntangu ya ntwadisulu, na zimbongo to mobile money, na kiedika yoso.",
  footer_tagline_accueil: "Nzo mosi, bisika mingi : zandu, kisika kia nteko ye nzila.",
  footer_tagline_gestion: "Kesi ye zandu, bibongisa mbote.",
