  accueil_descComptable: "— misomba ne mikenji bua mbongo mu nsalelu wa mbongo, nyongo ne bidi ne kupikula, kukuasa kwa nzubu, kufuta bena mudimu, kalandriya ka matuku a kufuta ne mabakulu adi mua kuangatibua. Tshidimu tshisambombo tsha budimuke, pashishe dolara 1 ku ngondo.",
