  accueil_questionMarket: "Udi musue kusomba anyi kuteka pa site?",
  accueil_descMarket: "— muaba udi wakanganya batekeshi ne basombeshi ba Kongo, mu bionso bidi : disaka, commande ne ditwadisha didibu bakuata, muaba udi muonso newe.",
  accueil_parcourirVitrine: "Tangila muaba wa mteko",
  apropos_h1: "Nzubu umue, bisumbu bisatu",
  apropos_intro: "ELEGANZ nkayidi mushindu wa mudimu udibu benze bua mudimu wa diambu dia Kongo, ku mutekeshi mukese too ne ku zando dinene : kulama misalu ya mbongo, kulombola zando ne kusomba pa site — bikuta bisatu bitapulukane, lutenga lumue, lwenze ne luendeshibue ku Kinshasa. Ditwadisha, didi too mpindieu dilombolwa kudi zando yonso ne bashofele bau, muinshi mua mudimu wabu bumuemue.",
  apropos_descComptable: "Mukanda wa kulombola dituku ne dituku bua mudimu wonso — mudimu, kukuasa, mudimu wa kuambuluisha, luendu — kakuena zando to catalogue bua kuenza. Misomba ne mikenji bua mbongo mu nsalelu wa mbongo, nyongo ne bidi ne kupikula ne kufuta pa tshitupa, kulombola kukuasa, kufuta bena mudimu, kalandriya ka matuku a kufuta, mifuanyi ne mabakulu adi mua kuangatibua, ne dibeji dia ntuadijilu bua kulomba mbongo. Tshidimu tshisambombo tsha budimuke, pashishe dolara 1 ku ngondo.",
  apropos_descGestion: "Kese, bintu ne fatule ya zando, ne denga didi diambuluishibua pa tshibadilu tshia kufuta, kukotesha/kubimbisha catalogue mu Excel, malapolo a mudimu makuatshisha, ditwadisha dia ma commande ne mikanji, kulombola tshisumbu, ne mushindu wa kakuyi internet udi ulama misomba yonso nansha mu tshikondo tshia réseau kakuyi.",
  apropos_descMarket: "Muaba udi wakanganya batekeshi ne basombeshi ba Kongo mu zando umue wa pa site, mu bionso bidi. Disaka, dibeji dia tshintu, dikutu, commande, ditwadisha dia ditwadisha ne meji a bena kusomba, bua kusomba bintu bia Kongo kakuyi kupatuka ku nzubu.",
  apropos_h2Engagement: "Tshitudi katuenzi",
